package validatepackage validate

import (
	"testing"

	"github.com/opencontainers/runc/libcontainer/configs"
	"github.com/opencontainers/runc/libcontainer/intelrdt"
)

func TestValidateIntelRdt(t *testing.T) {
	testCases := []struct {
		name       string
		rdtEnabled bool
		catEnabled bool
		mbaEnabled bool
		config     *configs.IntelRdt
		isErr      bool
	}{
		{
			name: "rdt not supported, no config",
		},
		{
			name:   "rdt not supported, with config",
			config: &configs.IntelRdt{},
			isErr:  true,
		},
		{
			name:       "empty config",
			rdtEnabled: true,
			config:     &configs.IntelRdt{},
		},
		{
			name:       "root clos",
			rdtEnabled: true,
			config: &configs.IntelRdt{
				ClosID: "/",
			},
		},
		{
			name:       "invalid ClosID (.)",
			rdtEnabled: true,
			config: &configs.IntelRdt{
				ClosID: ".",
			},
			isErr: true,
		},
		{
			name:       "invalid ClosID (..)",
			rdtEnabled: true,
			config: &configs.IntelRdt{
				ClosID: "..",
			},
			isErr: true,
		},
		{
			name:       "invalid ClosID (contains /)",
			rdtEnabled: true,
			config: &configs.IntelRdt{
				ClosID: "foo/bar",
			},
			isErr: true,
		},
		{
			name:       "cat not supported",
			rdtEnabled: true,
			config: &configs.IntelRdt{
				L3CacheSchema: "0=ff",
			},
			isErr: true,
		},
		{
			name:       "mba not supported",
			rdtEnabled: true,
			config: &configs.IntelRdt{
				MemBwSchema: "0=100",
			},
			isErr: true,
		},
		{
			name:       "valid config",
			rdtEnabled: true,
			catEnabled: true,
			mbaEnabled: true,
			config: &configs.IntelRdt{
				ClosID:        "clos-1",
				L3CacheSchema: "0=ff",
				MemBwSchema:   "0=100",
			},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			t.Cleanup(func() {
				intelRdtIsEnabled = intelrdt.IsEnabled
				intelRdtIsCATEnabled = intelrdt.IsCATEnabled
				intelRdtIsMBAEnabled = intelrdt.IsMBAEnabled
			})
			intelRdtIsEnabled = func() bool { return tc.rdtEnabled }
			intelRdtIsCATEnabled = func() bool { return tc.catEnabled }
			intelRdtIsMBAEnabled = func() bool { return tc.mbaEnabled }

			config := &configs.Config{
				Rootfs:   "/var",
				IntelRdt: tc.config,
			}

			err := Validate(config)
			if tc.isErr && err == nil {
				t.Error("expected error, got nil")
			}
			if !tc.isErr && err != nil {
				t.Error(err)
			}
		})
	}
}package validate

import (
	"github.com/opencontainers/runc/libcontainer/intelrdt"
)

// Allow mocking for TestValidateIntelRdt.
var (
	intelRdtIsEnabled    = intelrdt.IsEnabled
	intelRdtIsCATEnabled = intelrdt.IsCATEnabled
	intelRdtIsMBAEnabled = intelrdt.IsMBAEnabled
)package validate

import (
	"testing"

	"github.com/opencontainers/runc/libcontainer/configs"
)

func rootlessEUIDConfig() *configs.Config {
	return &configs.Config{
		Rootfs:          "/var",
		RootlessEUID:    true,
		RootlessCgroups: true,
		Namespaces: configs.Namespaces(
			[]configs.Namespace{
				{Type: configs.NEWUSER},
			},
		),
		UIDMappings: []configs.IDMap{
			{
				HostID:      1337,
				ContainerID: 0,
				Size:        1,
			},
		},
		GIDMappings: []configs.IDMap{
			{
				HostID:      7331,
				ContainerID: 0,
				Size:        1,
			},
		},
	}
}

func TestValidateRootlessEUID(t *testing.T) {
	config := rootlessEUIDConfig()
	if err := Validate(config); err != nil {
		t.Errorf("Expected error to not occur: %+v", err)
	}
}

/* rootlessEUIDMappings */

func TestValidateRootlessEUIDUserns(t *testing.T) {
	config := rootlessEUIDConfig()
	config.Namespaces = nil
	if err := Validate(config); err == nil {
		t.Errorf("Expected error to occur if user namespaces not set")
	}
}

func TestValidateRootlessEUIDMappingUid(t *testing.T) {
	config := rootlessEUIDConfig()
	config.UIDMappings = nil
	if err := Validate(config); err == nil {
		t.Errorf("Expected error to occur if no uid mappings provided")
	}
}

func TestValidateNonZeroEUIDMappingGid(t *testing.T) {
	config := rootlessEUIDConfig()
	config.GIDMappings = nil
	if err := Validate(config); err == nil {
		t.Errorf("Expected error to occur if no gid mappings provided")
	}
}

/* rootlessEUIDMount() */

func TestValidateRootlessEUIDMountUid(t *testing.T) {
	config := rootlessEUIDConfig()
	config.Mounts = []*configs.Mount{
		{
			Source:      "devpts",
			Destination: "/dev/pts",
			Device:      "devpts",
		},
	}

	if err := Validate(config); err != nil {
		t.Errorf("Expected error to not occur when uid= not set in mount options: %+v", err)
	}

	config.Mounts[0].Data = "uid=5"
	if err := Validate(config); err == nil {
		t.Errorf("Expected error to occur when setting uid=5 in mount options")
	}

	config.Mounts[0].Data = "uid=0"
	if err := Validate(config); err != nil {
		t.Errorf("Expected error to not occur when setting uid=0 in mount options: %+v", err)
	}

	config.Mounts[0].Data = "uid=2"
	config.UIDMappings[0].Size = 10
	if err := Validate(config); err != nil {
		t.Errorf("Expected error to not occur when setting uid=2 in mount options and UIDMappings[0].size is 10")
	}

	config.Mounts[0].Data = "uid=20"
	config.UIDMappings[0].Size = 10
	if err := Validate(config); err == nil {
		t.Errorf("Expected error to occur when setting uid=20 in mount options and UIDMappings[0].size is 10")
	}
}

