func TestValidateMounts(t *testing.T) {
	testCases := []struct {
		isErr bool
		dest  string
	}{
		{isErr: false, dest: "not/an/abs/path"},
		{isErr: false, dest: "./rel/path"},
		{isErr: false, dest: "./rel/path"},
		{isErr: false, dest: "../../path"},
		{isErr: false, dest: "/abs/path"},
		{isErr: false, dest: "/abs/but/../unclean"},
	}

	for _, tc := range testCases {
		config := &configs.Config{
			Rootfs: "/var",
			Mounts: []*configs.Mount{
				{Destination: tc.dest},
			},
		}

		err := Validate(config)
		if tc.isErr && err == nil {
			t.Errorf("mount dest: %s, expected error, got nil", tc.dest)
		}
		if !tc.isErr && err != nil {
			t.Errorf("mount dest: %s, expected nil, got error %v", tc.dest, err)
		}
	}
}

func TestValidateBindMounts(t *testing.T) {
	testCases := []struct {
		isErr bool
		flags int
		data  string
	}{
		{isErr: false, flags: 0, data: ""},
		{isErr: false, flags: unix.MS_RDONLY | unix.MS_NOSYMFOLLOW, data: ""},

		{isErr: true, flags: 0, data: "idmap"},
		{isErr: true, flags: unix.MS_RDONLY, data: "custom_ext4_flag"},
		{isErr: true, flags: unix.MS_NOATIME, data: "rw=foobar"},
	}

	for _, tc := range testCases {
		for _, bind := range []string{"bind", "rbind"} {
			bindFlag := map[string]int{
				"bind":  unix.MS_BIND,
				"rbind": unix.MS_BIND | unix.MS_REC,
			}[bind]

			config := &configs.Config{
				Rootfs: "/var",
				Mounts: []*configs.Mount{
					{
						Destination: "/",
						Flags:       tc.flags | bindFlag,
						Data:        tc.data,
					},
				},
			}

			err := Validate(config)
			if tc.isErr && err == nil {
				t.Errorf("%s mount flags:0x%x data:%v, expected error, got nil", bind, tc.flags, tc.data)
			}
			if !tc.isErr && err != nil {
				t.Errorf("%s mount flags:0x%x data:%v, expected nil, got error %v", bind, tc.flags, tc.data, err)
			}
		}
	}
}

func TestValidateIDMapMounts(t *testing.T) {
	mapping := []configs.IDMap{
		{
			ContainerID: 0,
			HostID:      10000,
			Size:        1,
		},
	}

	testCases := []struct {
		name   string
		isErr  bool
		config *configs.Config
	}{
		{
			name:  "idmap non-bind mount",
			isErr: true,
			config: &configs.Config{
				UIDMappings: mapping,
				GIDMappings: mapping,
				Mounts: []*configs.Mount{
					{
						Source:      "/dev/sda1",
						Destination: "/abs/path/",
						Device:      "ext4",
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name:  "idmap option non-bind mount",
			isErr: true,
			config: &configs.Config{
				Mounts: []*configs.Mount{
					{
						Source:      "/dev/sda1",
						Destination: "/abs/path/",
						Device:      "ext4",
						IDMapping:   &configs.MountIDMapping{},
					},
				},
			},
		},
		{
			name:  "ridmap option non-bind mount",
			isErr: true,
			config: &configs.Config{
				Mounts: []*configs.Mount{
					{
						Source:      "/dev/sda1",
						Destination: "/abs/path/",
						Device:      "ext4",
						IDMapping: &configs.MountIDMapping{
							Recursive: true,
						},
					},
				},
			},
		},
		{
			name:  "idmap mount no uid mapping",
			isErr: true,
			config: &configs.Config{
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name:  "idmap mount no gid mapping",
			isErr: true,
			config: &configs.Config{
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name:  "rootless idmap mount",
			isErr: true,
			config: &configs.Config{
				RootlessEUID: true,
				UIDMappings:  mapping,
				GIDMappings:  mapping,
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name: "idmap mounts without abs source path",
			config: &configs.Config{
				UIDMappings: mapping,
				GIDMappings: mapping,
				Mounts: []*configs.Mount{
					{
						Source:      "./rel/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name: "idmap mounts without abs dest path",
			config: &configs.Config{
				UIDMappings: mapping,
				GIDMappings: mapping,
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "./rel/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name: "simple idmap mount",
			config: &configs.Config{
				UIDMappings: mapping,
				GIDMappings: mapping,
				Mounts: []*configs.Mount{
					{
						Source:      "/another-abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name: "idmap mount with more flags",
			config: &configs.Config{
				UIDMappings: mapping,
				GIDMappings: mapping,
				Mounts: []*configs.Mount{
					{
						Source:      "/another-abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND | unix.MS_RDONLY,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name: "idmap mount without userns mappings",
			config: &configs.Config{
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name: "idmap mounts with different userns and mount mappings",
			config: &configs.Config{
				UIDMappings: mapping,
				GIDMappings: mapping,
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: []configs.IDMap{
								{
									ContainerID: 10,
									HostID:      10,
									Size:        1,
								},
							},
							GIDMappings: mapping,
						},
					},
				},
			},
		},
		{
			name: "idmap mounts with different userns and mount mappings",
			config: &configs.Config{
				UIDMappings: mapping,
				GIDMappings: mapping,
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							UIDMappings: mapping,
							GIDMappings: []configs.IDMap{
								{
									ContainerID: 10,
									HostID:      10,
									Size:        1,
								},
							},
						},
					},
				},
			},
		},
		{
			name:  "mount with 'idmap' option but no mappings",
			isErr: true,
			config: &configs.Config{
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping:   &configs.MountIDMapping{},
					},
				},
			},
		},
		{
			name:  "mount with 'ridmap' option but no mappings",
			isErr: true,
			config: &configs.Config{
				Mounts: []*configs.Mount{
					{
						Source:      "/abs/path/",
						Destination: "/abs/path/",
						Flags:       unix.MS_BIND,
						IDMapping: &configs.MountIDMapping{
							Recursive: true,
						},
					},
				},
			},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			config := tc.config
			config.Rootfs = "/var"

			err := mountsStrict(config)
			if tc.isErr && err == nil {
				t.Error("expected error, got nil")
			}

			if !tc.isErr && err != nil {
				t.Error(err)
			}
		})
	}
}

func TestValidateScheduler(t *testing.T) {
	testCases := []struct {
		isErr     bool
		policy    string
		niceValue int32
		priority  int32
		runtime   uint64
		deadline  uint64
		period    uint64
	}{
		{isErr: true, niceValue: 0},
		{isErr: false, policy: "SCHED_OTHER", niceValue: 19},
		{isErr: false, policy: "SCHED_OTHER", niceValue: -20},
		{isErr: true, policy: "SCHED_OTHER", niceValue: 20},
		{isErr: true, policy: "SCHED_OTHER", niceValue: -21},
		{isErr: true, policy: "SCHED_OTHER", priority: 100},
		{isErr: false, policy: "SCHED_FIFO", priority: 100},
		{isErr: true, policy: "SCHED_FIFO", runtime: 20},
		{isErr: true, policy: "SCHED_BATCH", deadline: 30},
		{isErr: true, policy: "SCHED_IDLE", period: 40},
		{isErr: true, policy: "SCHED_DEADLINE", priority: 100},
		{isErr: false, policy: "SCHED_DEADLINE", runtime: 200},
		{isErr: false, policy: "SCHED_DEADLINE", deadline: 300},
		{isErr: false, policy: "SCHED_DEADLINE", period: 400},
		{isErr: true, policy: "SCHED_OTHER", niceValue: 20},
		{isErr: true, policy: "SCHED_OTHER", niceValue: -21},
		{isErr: false, policy: "SCHED_FIFO", priority: 100, niceValue: 100},
	}

	for _, tc := range testCases {
		scheduler := configs.Scheduler{
			Policy:   specs.LinuxSchedulerPolicy(tc.policy),
			Nice:     tc.niceValue,
			Priority: tc.priority,
			Runtime:  tc.runtime,
			Deadline: tc.deadline,
			Period:   tc.period,
		}
		config := &configs.Config{
			Rootfs:    "/var",
			Scheduler: &scheduler,
		}

		err := Validate(config)
		if tc.isErr && err == nil {
			t.Errorf("scheduler: %d, expected error, got nil", tc.niceValue)
		}
		if !tc.isErr && err != nil {
			t.Errorf("scheduler: %d, expected nil, got error %v", tc.niceValue, err)
		}
	}
}

func TestValidateIOPriority(t *testing.T) {
	testCases := []struct {
		isErr    bool
		priority int
		class    specs.IOPriorityClass
	}{
		{isErr: false, priority: 0, class: specs.IOPRIO_CLASS_IDLE},
		{isErr: false, priority: 7, class: specs.IOPRIO_CLASS_RT},
		{isErr: false, priority: 3, class: specs.IOPRIO_CLASS_BE},
		// Invalid priority.
		{isErr: true, priority: -1, class: specs.IOPRIO_CLASS_BE},
		// Invalid class.
		{isErr: true, priority: 3, class: specs.IOPriorityClass("IOPRIO_CLASS_WOW")},
	}

	for _, tc := range testCases {
		ioPriroty := configs.IOPriority{
			Priority: tc.priority,
			Class:    tc.class,
		}
		config := &configs.Config{
			Rootfs:     "/var",
			IOPriority: &ioPriroty,
		}

		err := Validate(config)
		if tc.isErr && err == nil {
			t.Errorf("iopriority: %d, expected error, got nil", tc.priority)
		}
		if !tc.isErr && err != nil {
			t.Errorf("iopriority: %d, expected nil, got error %v", tc.priority, err)
		}
	}
}

func TestValidateNetDevices(t *testing.T) {
	testCases := []struct {
		name   string
		isErr  bool
		config *configs.Config
	}{
		{
			name: "network device with configured network namespace",
			config: &configs.Config{
				Namespaces: configs.Namespaces(
					[]configs.Namespace{
						{
							Type: configs.NEWNET,
							Path: "/var/run/netns/blue",
						},
					},
				),
				NetDevices: map[string]*configs.LinuxNetDevice{
					"eth0": {},
				},
			},
		},
		{
			name: "network device rename",
			config: &configs.Config{
				Namespaces: configs.Namespaces(
					[]configs.Namespace{
						{
							Type: configs.NEWNET,
							Path: "/var/run/netns/blue",
						},
					},
				),
				NetDevices: map[string]*configs.LinuxNetDevice{
					"eth0": {
						Name: "c0",
					},
				},
			},
		},
		{
			name: "network device network namespace created by runc",
			config: &configs.Config{
				Namespaces: configs.Namespaces(
					[]configs.Namespace{
						{
							Type: configs.NEWNET,
						},
					},
				),
				NetDevices: map[string]*configs.LinuxNetDevice{
					"eth0": {},
				},
			},
		},
		{
			name:  "network device network namespace empty",
			isErr: true,
			config: &configs.Config{
				Namespaces: configs.Namespaces(
					[]configs.Namespace{},
				),
				NetDevices: map[string]*configs.LinuxNetDevice{
					"eth0": {},
				},
			},
		},
		{
			name:  "network device rootless EUID",
			isErr: true,
			config: &configs.Config{
				Namespaces: configs.Namespaces(
					[]configs.Namespace{
						{
							Type: configs.NEWNET,
							Path: "/var/run/netns/blue",
						},
					},
				),
				RootlessEUID: true,
				NetDevices: map[string]*configs.LinuxNetDevice{
					"eth0": {},
				},
			},
		},
		{
			name:  "network device rootless",
			isErr: true,
			config: &configs.Config{
				Namespaces: configs.Namespaces(
					[]configs.Namespace{
						{
							Type: configs.NEWNET,
							Path: "/var/run/netns/blue",
						},
					},
				),
				RootlessCgroups: true,
				NetDevices: map[string]*configs.LinuxNetDevice{
					"eth0": {},
				},
			},
		},
		{
			name:  "network device bad name",
			isErr: true,
			config: &configs.Config{
				Namespaces: configs.Namespaces(
					[]configs.Namespace{
						{
							Type: configs.NEWNET,
							Path: "/var/run/netns/blue",
						},
					},
				),
				NetDevices: map[string]*configs.LinuxNetDevice{
					"eth0": {
						Name: "eth0/",
					},
				},
			},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			config := tc.config
			config.Rootfs = "/var"

			err := Validate(config)
			if tc.isErr && err == nil {
				t.Error("expected error, got nil")
			}

			if !tc.isErr && err != nil {
				t.Error(err)
			}
		})
	}
}

func TestValidateUserSysctlWithUserNamespace(t *testing.T) {
	if _, err := os.Stat("/proc/self/ns/user"); errors.Is(err, os.ErrNotExist) {
		t.Skip("Test requires userns.")
	}
	config := &configs.Config{
		Rootfs: "/var",
		Sysctl: map[string]string{"user.max_inotify_watches": "8192"},
		Namespaces: configs.Namespaces(
			[]configs.Namespace{
				{Type: configs.NEWUSER},
			},
		),
		UIDMappings: []configs.IDMap{{HostID: 0, ContainerID: 123, Size: 100}},
		GIDMappings: []configs.IDMap{{HostID: 0, ContainerID: 123, Size: 100}},
	}

	err := Validate(config)
	if err != nil {
		t.Errorf("Expected error to not occur with user.* sysctl and NEWUSER namespace: %+v", err)
	}
}

func TestValidateUserSysctlWithoutUserNamespace(t *testing.T) {
	config := &configs.Config{
		Rootfs: "/var",
		Sysctl: map[string]string{"user.max_inotify_watches": "8192"},
	}

	err := Validate(config)
	if err == nil {
		t.Error("Expected error to occur with user.* sysctl without NEWUSER namespace but it was nil")
	}
}

func TestDevValidName(t *testing.T) {
	testCases := []struct {
		name  string
		valid bool
	}{
		{name: "", valid: false},
		{name: "a", valid: true},
		{name: strings.Repeat("a", unix.IFNAMSIZ), valid: true},
		{name: strings.Repeat("a", unix.IFNAMSIZ+1), valid: false},
		{name: ".", valid: false},
		{name: "..", valid: false},
		{name: "dev/null", valid: false},
		{name: "valid:name", valid: false},
		{name: "valid name", valid: false},
	}
	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			if devValidName(tc.name) != tc.valid {
				t.Fatalf("name %q, expected valid: %v", tc.name, tc.valid)
			}
		})
	}
}package validate

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"github.com/opencontainers/cgroups"
	"github.com/opencontainers/runc/libcontainer/configs"
	"github.com/opencontainers/runtime-spec/specs-go"
	selinux "github.com/opencontainers/selinux/go-selinux"
	"github.com/sirupsen/logrus"
	"golang.org/x/sys/unix"
)

type check func(config *configs.Config) error

func Validate(config *configs.Config) error {
	checks := []check{
		cgroupsCheck,
		rootfs,
		network,
		netdevices,
		uts,
		security,
		namespaces,
		sysctl,
		intelrdtCheck,
		rootlessEUIDCheck,
		mountsStrict,
		scheduler,
		ioPriority,
		memoryPolicy,
	}
	for _, c := range checks {
		if err := c(config); err != nil {
			return err
		}
	}
	// Relaxed validation rules for backward compatibility
	warns := []check{
		mountsWarn,
	}
	for _, c := range warns {
		if err := c(config); err != nil {
			logrus.WithError(err).Warn("configuration")
		}
	}
	return nil
}

// rootfs validates if the rootfs is an absolute path and is not a symlink
// to the container's root filesystem.
func rootfs(config *configs.Config) error {
	if _, err := os.Stat(config.Rootfs); err != nil {
		return fmt.Errorf("invalid rootfs: %w", err)
	}
	cleaned, err := filepath.Abs(config.Rootfs)
	if err != nil {
		return fmt.Errorf("invalid rootfs: %w", err)
	}
	if cleaned, err = filepath.EvalSymlinks(cleaned); err != nil {
		return fmt.Errorf("invalid rootfs: %w", err)
	}
	if filepath.Clean(config.Rootfs) != cleaned {
		return errors.New("invalid rootfs: not an absolute path, or a symlink")
	}
	return nil
}

// https://elixir.bootlin.com/linux/v6.12/source/net/core/dev.c#L1066
func devValidName(name string) bool {
	if len(name) == 0 || len(name) > unix.IFNAMSIZ {
		return false
	}
	if name == "." || name == ".." {
		return false
	}
	if strings.ContainsAny(name, "/: ") {
		return false
	}
	return true
}

func netdevices(config *configs.Config) error {
	if len(config.NetDevices) == 0 {
		return nil
	}
	if !config.Namespaces.Contains(configs.NEWNET) {
		return errors.New("unable to move network devices without a NET namespace")
	}

	if config.RootlessEUID || config.RootlessCgroups {
		return errors.New("network devices are not supported for rootless containers")
	}

	for name, netdev := range config.NetDevices {
		if !devValidName(name) {
			return fmt.Errorf("invalid network device name %q", name)
		}
		if netdev.Name != "" && !devValidName(netdev.Name) {
			return fmt.Errorf("invalid network device name %q", netdev.Name)
		}
	}
	return nil
}

func network(config *configs.Config) error {
	if !config.Namespaces.Contains(configs.NEWNET) {
		if len(config.Networks) > 0 || len(config.Routes) > 0 {
			return errors.New("unable to apply network settings without a private NET namespace")
		}
	}
	return nil
}

func uts(config *configs.Config) error {
	if config.Hostname != "" && !config.Namespaces.Contains(configs.NEWUTS) {
		return errors.New("unable to set hostname without a private UTS namespace")
	}
	if config.Domainname != "" && !config.Namespaces.Contains(configs.NEWUTS) {
		return errors.New("unable to set domainname without a private UTS namespace")
	}
	return nil
}

func security(config *configs.Config) error {
	// restrict sys without mount namespace
	if (len(config.MaskPaths) > 0 || len(config.ReadonlyPaths) > 0) &&
		!config.Namespaces.Contains(configs.NEWNS) {
		return errors.New("unable to restrict sys entries without a private MNT namespace")
	}
	if config.ProcessLabel != "" && !selinux.GetEnabled() {
		return errors.New("selinux label is specified in config, but selinux is disabled or not supported")
	}

	return nil
}

func namespaces(config *configs.Config) error {
	if config.Namespaces.Contains(configs.NEWUSER) {
		if _, err := os.Stat("/proc/self/ns/user"); errors.Is(err, os.ErrNotExist) {
			return errors.New("user namespaces aren't enabled in the kernel")
		}
		hasPath := config.Namespaces.PathOf(configs.NEWUSER) != ""
		hasMappings := config.UIDMappings != nil || config.GIDMappings != nil
		if !hasPath && !hasMappings {
			return errors.New("user namespaces enabled, but no namespace path to join nor mappings to apply specified")
		}
		// The hasPath && hasMappings validation case is handled in specconv --
		// we cache the mappings in Config during specconv in the hasPath case,
		// so we cannot do that validation here.
	} else {
		if config.UIDMappings != nil || config.GIDMappings != nil {
			return errors.New("user namespace mappings specified, but user namespace isn't enabled in the config")
		}
	}

	if config.Namespaces.Contains(configs.NEWCGROUP) {
		if _, err := os.Stat("/proc/self/ns/cgroup"); errors.Is(err, os.ErrNotExist) {
			return errors.New("cgroup namespaces aren't enabled in the kernel")
		}
	}

	if config.Namespaces.Contains(configs.NEWTIME) {
		if _, err := os.Stat("/proc/self/timens_offsets"); errors.Is(err, os.ErrNotExist) {
			return errors.New("time namespaces aren't enabled in the kernel")
		}
		hasPath := config.Namespaces.PathOf(configs.NEWTIME) != ""
		hasOffsets := config.TimeOffsets != nil
		if hasPath && hasOffsets {
			return errors.New("time namespace enabled, but both namespace path and time offsets specified -- you may only provide one")
		}
	} else {
		if config.TimeOffsets != nil {
			return errors.New("time namespace offsets specified, but time namespace isn't enabled in the config")
		}
	}

	return nil
}

// convertSysctlVariableToDotsSeparator can return sysctl variables in dots separator format.
// The '/' separator is also accepted in place of a '.'.
// Convert the sysctl variables to dots separator format for validation.
// More info: sysctl(8), sysctl.d(5).
//
// For example:
// Input sysctl variable "net/ipv4/conf/eno2.100.rp_filter"
// will return the converted value "net.ipv4.conf.eno2/100.rp_filter"
func convertSysctlVariableToDotsSeparator(val string) string {
	if val == "" {
		return val
	}
	firstSepIndex := strings.IndexAny(val, "./")
	if firstSepIndex == -1 || val[firstSepIndex] == '.' {
		return val
	}

	f := func(r rune) rune {
		switch r {
		case '.':
			return '/'
		case '/':
			return '.'
		}
		return r
	}
	return strings.Map(f, val)
}

// sysctl validates that the specified sysctl keys are valid or not.
// /proc/sys isn't completely namespaced and depending on which namespaces
// are specified, a subset of sysctls are permitted.
func sysctl(config *configs.Config) error {
	validSysctlMap := map[string]bool{
		"kernel.msgmax":          true,
		"kernel.msgmnb":          true,
		"kernel.msgmni":          true,
		"kernel.sem":             true,
		"kernel.shmall":          true,
		"kernel.shmmax":          true,
		"kernel.shmmni":          true,
		"kernel.shm_rmid_forced": true,
	}

	var (
		netOnce    sync.Once
		hostnet    bool
		hostnetErr error
	)

	for s := range config.Sysctl {
		s := convertSysctlVariableToDotsSeparator(s)
		if validSysctlMap[s] || strings.HasPrefix(s, "fs.mqueue.") {
			if config.Namespaces.Contains(configs.NEWIPC) {
				continue
			} else {
				return fmt.Errorf("sysctl %q is not allowed in the hosts ipc namespace", s)
			}
		}
		if strings.HasPrefix(s, "net.") {
			// Is container using host netns?
			// Here "host" means "current", not "initial".
			netOnce.Do(func() {
				if !config.Namespaces.Contains(configs.NEWNET) {
					hostnet = true
					return
				}
				path := config.Namespaces.PathOf(configs.NEWNET)
				if path == "" {
					// own netns, so hostnet = false
					return
				}
				hostnet, hostnetErr = isHostNetNS(path)
			})
			if hostnetErr != nil {
				return fmt.Errorf("invalid netns path: %w", hostnetErr)
			}
			if hostnet {
				return fmt.Errorf("sysctl %q not allowed in host network namespace", s)
			}
			continue
		}
		if config.Namespaces.Contains(configs.NEWUTS) {
			switch s {
			case "kernel.domainname":
				// This is namespaced and there's no explicit OCI field for it.
				continue
			case "kernel.hostname":
				// This is namespaced but there's a conflicting (dedicated) OCI field for it.
				return fmt.Errorf("sysctl %q is not allowed as it conflicts with the OCI %q field", s, "hostname")
			}
		}

		if strings.HasPrefix(s, "user.") {

			// while it is technically true that a non-userns
			// container can write to /proc/sys/user on behalf of
			// the init_user_ns, it was not previously supported,
			// and doesn't guarantee that someone else spawns a
			// different container and writes there, changing the
			// values. in particular, setting something like
			// max_user_namespaces to non-zero could be a vector to
			// use 0-days where the admin had previously disabled
			// them.
			//
			// additionally, this setting affects other host
			// processes that are not container related.
			//
			// so let's refuse this unless we know for sure it
			// won't touch anything else.
			if !config.Namespaces.Contains(configs.NEWUSER) {
				return fmt.Errorf("setting ucounts without a user namespace not allowed: %v", s)
			}
			continue
		}

		return fmt.Errorf("sysctl %q is not in a separate kernel namespace", s)
	}

	return nil
}

func intelrdtCheck(config *configs.Config) error {
	if config.IntelRdt == nil {
		return nil
	}
	if !intelRdtIsEnabled() {
		return fmt.Errorf("intelRdt is specified in config, but Intel RDT is not enabled")
	}

	switch clos := config.IntelRdt.ClosID; {
	case clos == ".", clos == "..", len(clos) > 1 && strings.Contains(clos, "/"):
		return fmt.Errorf("invalid intelRdt.ClosID %q", clos)
	}
	if !intelRdtIsCATEnabled() && config.IntelRdt.L3CacheSchema != "" {
		return errors.New("intelRdt.l3CacheSchema is specified in config, but Intel RDT/CAT is not enabled")
	}
	if !intelRdtIsMBAEnabled() && config.IntelRdt.MemBwSchema != "" {
		return errors.New("intelRdt.memBwSchema is specified in config, but Intel RDT/MBA is not enabled")
	}

	return nil
}

func cgroupsCheck(config *configs.Config) error {
	c := config.Cgroups
	if c == nil {
		return nil
	}

	if (c.Name != "" || c.Parent != "") && c.Path != "" {
		return fmt.Errorf("cgroup: either Path or Name and Parent should be used, got %+v", c)
	}

	r := c.Resources
	if r == nil {
		return nil
	}

	if !cgroups.IsCgroup2UnifiedMode() && r.Unified != nil {
		return cgroups.ErrV1NoUnified
	}

	if cgroups.IsCgroup2UnifiedMode() {
		_, err := cgroups.ConvertMemorySwapToCgroupV2Value(r.MemorySwap, r.Memory)
		if err != nil {
			return err
		}
	}

	return nil
}

func checkBindOptions(m *configs.Mount) error {
	if !m.IsBind() {
		return nil
	}
	// We must reject bind-mounts that also have filesystem-specific mount
	// options, because the kernel will completely ignore these flags and we
	// cannot set them per-mountpoint.
	//
	// It should be noted that (due to how the kernel caches superblocks), data
	// options could also silently ignored for other filesystems even when
	// doing a fresh mount, but there is no real way to avoid this (and it
	// matches how everything else works). There have been proposals to make it
	// possible for userspace to detect this caching, but this wouldn't help
	// runc because the behaviour wouldn't even be desirable for most users.
	if m.Data != "" {
		return errors.New("bind mounts cannot have any filesystem-specific options applied")
	}
	return nil
}

func checkIDMapMounts(config *configs.Config, m *configs.Mount) error {
	// Make sure MOUNT_ATTR_IDMAP is not set on any of our mounts. This
	// attribute is handled differently to all other attributes (through
	// m.IDMapping), so make sure we never store it in the actual config. This
	// really shouldn't ever happen.
	if m.RecAttr != nil && (m.RecAttr.Attr_set|m.RecAttr.Attr_clr)&unix.MOUNT_ATTR_IDMAP != 0 {
		return errors.New("mount configuration cannot contain recAttr for MOUNT_ATTR_IDMAP")
	}
	if !m.IsIDMapped() {
		return nil
	}
	if !m.IsBind() {
		return errors.New("id-mapped mounts are only supported for bind-mounts")
	}
	if config.RootlessEUID {
		return errors.New("id-mapped mounts are not supported for rootless containers")
	}
	if m.IDMapping.UserNSPath == "" {
		if len(m.IDMapping.UIDMappings) == 0 || len(m.IDMapping.GIDMappings) == 0 {
			return errors.New("id-mapped mounts must have both uid and gid mappings specified")
		}
	} else {
		if m.IDMapping.UIDMappings != nil || m.IDMapping.GIDMappings != nil {
			// should never happen
			return errors.New("[internal error] id-mapped mounts cannot have both userns_path and uid and gid mappings specified")
		}
	}
	return nil
}

func mountsWarn(config *configs.Config) error {
	for _, m := range config.Mounts {
		if !filepath.IsAbs(m.Destination) {
			return fmt.Errorf("mount %+v: relative destination path is **deprecated**, using it as relative to /", m)
		}
	}
	return nil
}

func mountsStrict(config *configs.Config) error {
	for _, m := range config.Mounts {
		if err := checkBindOptions(m); err != nil {
			return fmt.Errorf("invalid mount %+v: %w", m, err)
		}
		if err := checkIDMapMounts(config, m); err != nil {
			return fmt.Errorf("invalid mount %+v: %w", m, err)
		}
	}
	return nil
}

func isHostNetNS(path string) (bool, error) {
	const currentProcessNetns = "/proc/self/ns/net"

	var st1, st2 unix.Stat_t

	if err := unix.Stat(currentProcessNetns, &st1); err != nil {
		return false, &os.PathError{Op: "stat", Path: currentProcessNetns, Err: err}
	}
	if err := unix.Stat(path, &st2); err != nil {
		return false, &os.PathError{Op: "stat", Path: path, Err: err}
	}

	return (st1.Dev == st2.Dev) && (st1.Ino == st2.Ino), nil
}

// scheduler is to validate scheduler configs according to https://man7.org/linux/man-pages/man2/sched_setattr.2.html
func scheduler(config *configs.Config) error {
	s := config.Scheduler
	if s == nil {
		return nil
	}
	if s.Policy == "" {
		return errors.New("scheduler policy is required")
	}
	if s.Policy == specs.SchedOther || s.Policy == specs.SchedBatch {
		if s.Nice < -20 || s.Nice > 19 {
			return fmt.Errorf("invalid scheduler.nice: %d when scheduler.policy is %s", s.Nice, string(s.Policy))
		}
	}
	if s.Priority != 0 && (s.Policy != specs.SchedFIFO && s.Policy != specs.SchedRR) {
		return errors.New("scheduler.priority can only be specified for SchedFIFO or SchedRR policy")
	}
	if s.Policy != specs.SchedDeadline && (s.Runtime != 0 || s.Deadline != 0 || s.Period != 0) {
		return errors.New("scheduler runtime/deadline/period can only be specified for SchedDeadline policy")
	}
	return nil
}

func ioPriority(config *configs.Config) error {
	if config.IOPriority == nil {
		return nil
	}
	priority := config.IOPriority.Priority
	if priority < 0 || priority > 7 {
		return fmt.Errorf("invalid ioPriority.Priority: %d", priority)
	}

	switch class := config.IOPriority.Class; class {
	case specs.IOPRIO_CLASS_RT, specs.IOPRIO_CLASS_BE, specs.IOPRIO_CLASS_IDLE:
		// Valid class, do nothing.
	default:
		return fmt.Errorf("invalid ioPriority.Class: %q", class)
	}

	return nil
}

func memoryPolicy(config *configs.Config) error {
	mpol := config.MemoryPolicy
	if mpol == nil {
		return nil
	}
	switch mpol.Mode {
	case unix.MPOL_DEFAULT, unix.MPOL_LOCAL:
		if mpol.Nodes != nil && mpol.Nodes.Count() != 0 {
			return fmt.Errorf("memory policy mode requires 0 nodes but got %d", mpol.Nodes.Count())
		}
	case unix.MPOL_BIND, unix.MPOL_INTERLEAVE,
		unix.MPOL_PREFERRED_MANY, unix.MPOL_WEIGHTED_INTERLEAVE:
		if mpol.Nodes == nil || mpol.Nodes.Count() == 0 {
			return fmt.Errorf("memory policy mode requires at least one node but got 0")
		}
	case unix.MPOL_PREFERRED:
		// Zero or more nodes are allowed by the kernel.
	default:
		return fmt.Errorf("invalid memory policy mode: %d", mpol.Mode)
	}
	return nil
