// container to be setup with the host's networking stack
type Network struct {
	// Type sets the networks type, commonly veth and loopback.
	Type string `json:"type"`

	// Name of the network interface.
	Name string `json:"name,omitempty"`

	// The bridge to use.
	Bridge string `json:"bridge,omitempty"`

	// MacAddress contains the MAC address to set on the network interface.
	MacAddress string `json:"mac_address,omitempty"`

	// Address contains the IPv4 and mask to set on the network interface.
	Address string `json:"address,omitempty"`

	// Gateway sets the gateway address that is used as the default for the interface.
	Gateway string `json:"gateway,omitempty"`

	// IPv6Address contains the IPv6 and mask to set on the network interface.
	IPv6Address string `json:"ipv6_address,omitempty"`

	// IPv6Gateway sets the ipv6 gateway address that is used as the default for the interface.
	IPv6Gateway string `json:"ipv6_gateway,omitempty"`

	// Mtu sets the mtu value for the interface and will be mirrored on both the host and
	// container's interfaces if a pair is created, specifically in the case of type veth
	// Note: This does not apply to loopback interfaces.
	Mtu int `json:"mtu,omitempty"`

	// TxQueueLen sets the tx_queuelen value for the interface and will be mirrored on both the host and
	// container's interfaces if a pair is created, specifically in the case of type veth
	// Note: This does not apply to loopback interfaces.
	TxQueueLen int `json:"txqueuelen,omitempty"`

	// HostInterfaceName is a unique name of a veth pair that resides on in the host interface of the
	// container.
	HostInterfaceName string `json:"host_interface_name,omitempty"`

	// HairpinMode specifies if hairpin NAT should be enabled on the virtual interface
	// bridge port in the case of type veth
	// Note: This is unsupported on some systems.
	// Note: This does not apply to loopback interfaces.
	HairpinMode bool `json:"hairpin_mode,omitempty"`
}

// Route defines a routing table entry.
//
// Routes can be specified to create entries in the routing table as the container
// is started.
//
// All of destination, source, and gateway should be either IPv4 or IPv6.
// One of the three options must be present, and omitted entries will use their
// IP family default for the route table.  For IPv4 for example, setting the
// gateway to 1.2.3.4 and the interface to eth0 will set up a standard
// destination of 0.0.0.0(or *) when viewed in the route table.
type Route struct {
	// Destination specifies the destination IP address and mask in the CIDR form.
	Destination string `json:"destination,omitempty"`

	// Source specifies the source IP address and mask in the CIDR form.
	Source string `json:"source,omitempty"`

	// Gateway specifies the gateway IP address.
	Gateway string `json:"gateway,omitempty"`

	// InterfaceName specifies the device to set this route up for, for example eth0.
	InterfaceName string `json:"interface_name,omitempty"`
}package configs

import (
	"testing"

	"golang.org/x/sys/unix"
)

func TestToCPUSet(t *testing.T) {
	set := func(cpus ...int) *unix.CPUSet {
		r := &unix.CPUSet{}
		for _, cpu := range cpus {
			r.Set(cpu)
		}
		return r
	}

	testCases := []struct {
		in    string
		out   *unix.CPUSet
		isErr bool
	}{
		{in: ""}, // Empty means unset.

		// Valid cases.
		{in: "0", out: &unix.CPUSet{1}},
		{in: "1", out: &unix.CPUSet{2}},
		{in: "0-1", out: &unix.CPUSet{3}},
		{in: "0,1", out: &unix.CPUSet{3}},
		{in: ",0,1,", out: &unix.CPUSet{3}},
		{in: "0-3", out: &unix.CPUSet{0x0f}},
		{in: "0,1,2-3", out: &unix.CPUSet{0x0f}},
		{in: "4-7", out: &unix.CPUSet{0xf0}},
		{in: "0-7", out: &unix.CPUSet{0xff}},
		{in: "0-15", out: &unix.CPUSet{0xffff}},
		{in: "16", out: &unix.CPUSet{0x10000}},
		// Extra whitespace in between ranges are OK.
		{in: "1, 2, 1-2", out: &unix.CPUSet{6}},
		{in: "    , 1   , 3  ,  5-7,    ", out: &unix.CPUSet{0xea}},
		// Somewhat large values. The underlying type in unix.CPUSet
		// can either be uint32 or uint64, so we have to use a helper.
		{in: "0-3,32-33", out: set(0, 1, 2, 3, 32, 33)},
		{in: "127-129, 1", out: set(1, 127, 128, 129)},
		{in: "1023", out: set(1023)},

		// Error cases.
		{in: "-", isErr: true},
		{in: "1-", isErr: true},
		{in: "-3", isErr: true},
		{in: ",", isErr: true},
		{in: " ", isErr: true},
		// Bad range (start > end).
		{in: "54-53", isErr: true},
		// Extra spaces inside a range is not OK.
		{in: "1 - 2", isErr: true},
		{in: "1024", isErr: true}, // Too big for unix.CPUSet.
	}

	for _, tc := range testCases {
		t.Run(tc.in, func(t *testing.T) {
			out, err := ToCPUSet(tc.in)
			t.Logf("ToCPUSet(%q) = %v (error: %v)", tc.in, out, err)
			// Check the error.
			if tc.isErr {
				if err == nil {
					t.Error("want error, got nil")
				}
				return // No more checks.
			}
			if err != nil {
				t.Fatalf("want no error, got %v", err)
			}
			// Check the value.
			if tc.out == nil {
				if out != nil {
					t.Fatalf("want nil, got %v", out)
				}
				return // No more checks.
			}
			if out == nil {
				t.Fatalf("want %v, got nil", tc.out)
			}
			if *out != *tc.out {
				t.Errorf("case %q: want %v, got %v", tc.in, tc.out, out)
			}
		})
	}
}
